// The two surface tiles, embedded so the page also runs from file:// (an <img> from
// a file:// origin taints WebGL textures; a data: URI does not). Regenerate with
// tools/textures.py + tools/embed-textures.py.
export const TEXTURES = {
  carpetMap: 'data:image/webp;base64,',
  carpetNormal: 'data:image/webp;base64,',
  walnutMap: 'data:image/webp;base64,',
  walnutRough: 'data:image/webp;base64,',
  wallMap: 'data:image/webp;base64,',
  wallNormal: 'data:image/webp;base64,',
};
